INSERT INTO encounter_methods (id, identifier, `order`) SELECT @base + (@n := @n + 1), m.identifier, @base_ord + @n FROM (SELECT DISTINCT method_identifier AS identifier FROM oras_stage) m WHERE NOT EXISTS (SELECT 1 FROM encounter_methods x WHERE x.identifier = m.identifier);
INSERT INTO location_areas (id, location_id, game_index, identifier) SELECT @base + (@n := @n + 1), l.id, 0, '' FROM locations l WHERE l.identifier IN (SELECT DISTINCT location_identifier FROM oras_stage) AND NOT EXISTS (SELECT 1 FROM location_areas la WHERE la.location_id = l.id);
INSERT INTO location_areas (id, location_id, game_index, identifier) SELECT @base + (@n := @n + 1), x.location_id, 0, x.area_identifier FROM (SELECT DISTINCT l.id AS location_id, s.area_identifier FROM oras_stage s JOIN locations l ON l.identifier = s.location_identifier WHERE s.area_identifier IS NOT NULL AND NOT EXISTS (SELECT 1 FROM location_areas la WHERE la.location_id = l.id AND la.identifier = s.area_identifier)) x;
INSERT INTO encounter_slots (id, version_group_id, encounter_method_id, slot, rarity) SELECT @base + (@n := @n + 1), 16, n.mid, n.slot, n.rarity FROM (SELECT DISTINCT em.id AS mid, s.slot, s.rarity FROM oras_stage s JOIN encounter_methods em ON em.identifier = s.method_identifier) n WHERE NOT EXISTS (SELECT 1 FROM encounter_slots x WHERE x.version_group_id = 16 AND x.encounter_method_id = n.mid AND x.slot = n.slot AND x.rarity = n.rarity);
INSERT INTO encounters (id, version_id, location_area_id, encounter_slot_id, pokemon_id, min_level, max_level) SELECT @base + (@n := @n + 1), r.version_id, r.area_id, r.slot_id, r.pokemon_id, r.min_level, r.max_level FROM (SELECT DISTINCT s.version_id, CASE WHEN s.area_identifier IS NULL THEN (SELECT MIN(la.id) FROM location_areas la WHERE la.location_id = l.id) ELSE (SELECT MIN(la.id) FROM location_areas la WHERE la.location_id = l.id AND la.identifier = s.area_identifier) END AS area_id, (SELECT MIN(es.id) FROM encounter_slots es WHERE es.version_group_id = 16 AND es.encounter_method_id = em.id AND es.slot = s.slot AND es.rarity = s.rarity) AS slot_id, em.id AS method_id, s.pokemon_id, s.min_level, s.max_level FROM oras_stage s JOIN locations l ON l.identifier = s.location_identifier JOIN encounter_methods em ON em.identifier = s.method_identifier) r WHERE r.area_id IS NOT NULL AND r.slot_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM oras_have h WHERE h.version_id = r.version_id AND h.location_area_id = r.area_id AND h.encounter_method_id = r.method_id);
